#[cfg(test)]
mod every_member {
    #![allow(clippy::unwrap_used, reason = "a test fails by panicking")]

    use super::*;

    #[test]
    fn every_member_reads_whole_and_comes_back() {
        for member in HolidayScope::ALL {
            assert_eq!(HolidayScope::from_key(member.key()), Some(member));
            assert_eq!(HolidayScope::from_id(member.id()), Some(member));
            assert_eq!(HolidayScope::try_from(member.key_id()), Ok(member));
            assert_eq!(member.full_key(), format!("{}.{}", Kind::HolidayScope.name(), member.key()));
            assert_eq!(member.full_key().parse::<HolidayScope>(), Ok(member));
            assert_eq!(member.to_string().parse::<HolidayScope>(), Ok(member));
            let json = serde_json::to_string(&member).unwrap();
            assert_eq!(serde_json::from_str::<HolidayScope>(&json).unwrap(), member);
            assert_eq!(<HolidayScope as Catalogued>::mark(member), member.mark());
            assert_ne!(member.doc(), "");
            assert_ne!(member.glyph(), Some(""));
            let _ = (member.deprecated(), member.sources(), member.unverified());
        }
        assert_eq!(HolidayScope::ALL.len(), Kind::HolidayScope.count());
    }
}
